const normalizeData = (stored: Partial<AppData>): AppData => ({
  ...defaultData, ...stored,
  tasks: (stored.tasks ?? defaultData.tasks).filter(t => t.area !== ('Youth Troop' as Area)) as Task[],
  classes: stored.classes ?? defaultData.classes,
  classNotes: stored.classNotes ?? [],
  scholarships: stored.scholarships ?? defaultData.scholarships,
  exams: stored.exams ?? defaultData.exams,
  lessons: stored.lessons?.length ? stored.lessons.map(l => ({ ...lessonSeed[0], ...l, level: l.level ?? (l as unknown as { program?: string }).program ?? 'First Aid', title: l.title ?? `${l.level ?? 'Lesson'} plan`, notes: l.notes ?? '' })) : defaultData.lessons,
  workLogs: stored.workLogs ?? defaultData.workLogs,
  events: (stored.events ?? defaultData.events).filter(e => e.category !== 'Youth Troop').map(e => ({ ...e, color: e.color ?? categoryColors[e.category] ?? '#D7D0E5' })),
  notes: stored.notes ?? defaultData.notes,
  lifeEntries: stored.lifeEntries ?? defaultData.lifeEntries,
  milestones: stored.milestones ?? defaultData.milestones,
  resources: stored.resources ?? defaultData.resources,
  reset: { ...defaultData.reset, ...(stored.reset ?? {}) },
});

type SyncStatus = 'loading' | 'saving' | 'saved' | 'local' | 'offline';
type DashboardContextValue = {
  data: AppData;
  setData: React.Dispatch<React.SetStateAction<AppData>>;
  ready: boolean;
  syncStatus: SyncStatus;
  uploadImage: (file: File) => Promise<string>;
};

const loadLocalData = (): AppData => {
  try {
    const stored = localStorage.getItem('senior-year-dashboard-data');
    return stored ? normalizeData(JSON.parse(stored) as Partial<AppData>) : defaultData;
  } catch {
    return defaultData;
  }
};

const DashboardContext = createContext<DashboardContextValue | null>(null);
const useDashboard = () => { const ctx = useContext(DashboardContext); if (!ctx) throw new Error('Dashboard context missing'); return ctx; };

function DashboardProvider({ children }: { children: ReactNode }) {
  const [data, setData] = useState<AppData>(loadLocalData);
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('local');

  useEffect(() => {
    try {
      localStorage.setItem('senior-year-dashboard-data', JSON.stringify(data));
      setSyncStatus('saved');
    } catch {
      setSyncStatus('offline');
    }
  }, [data]);

  return <DashboardContext.Provider value={{
    data,
    setData,
    ready: true,
    syncStatus,
    uploadImage: async (file: File) => {
      return await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result));
        reader.onerror = () => reject(new Error('The image could not be loaded.'));
        reader.readAsDataURL(file);
      });
    },
  }}>{children}</DashboardContext.Provider>;
}
